export function acoustic(scenario='normal',rpm=1200,noise=15){const deviations={normal:0,friction:48,loose:67};const score=Math.min(100,Math.round(8+deviations[scenario]+noise*.18));return {score,rms:(.11+(deviations[scenario]||0)/250+noise/500).toFixed(2),frequency:Math.round(rpm/60),status:score>40?'Desvio identificado':'Dentro do padrão',reason:scenario==='normal'?'Harmónicos regulares para este regime de rotação.':scenario==='friction'?'Energia adicional nas frequências superiores.':'Impulsos periódicos e modulação irregular.'};}
export const assemblySteps=['Posicionar base','Inserir eixo','Colocar anilha','Montar roda','Apertar porca','Inspeção final'];
export function assemblyResult(completed){const missing=assemblySteps.filter((_,i)=>!completed.includes(i));return {missing,complete:!missing.length,progress:Math.round(completed.length/assemblySteps.length*100)};}
export function planOrders(duplicate=true,ambiguous=true){const rows=[{id:'PED-1041',client:'Atlas Manufacturing',item:'Sensores ambientais',qty:12},{id:'PED-1042',client:ambiguous?'Nova':'Nova Robotics',item:'Câmaras industriais',qty:2},{id:'PED-1043',client:'Coura Systems',item:'Controladores',qty:4}];if(duplicate)rows.push({...rows[0]});const seen=new Set();return rows.map(row=>{let status=seen.has(row.id)?'duplicate':row.client==='Nova'?'review':'ready';seen.add(row.id);return {...row,status};});}
export const visionSamples=[{id:'V-01',type:'gear',label:'Engrenagem',confidence:.94},{id:'V-02',type:'bolt',label:'Parafuso',confidence:.91},{id:'V-03',type:'washer',label:'Anilha',confidence:.88},{id:'V-04',type:'unknown',label:'Desconhecido',confidence:.43}];
export function classifySamples(light,threshold,learned={}){return visionSamples.map(x=>{const confidence=learned[x.id]?Math.max(.7,.92-light*.001):Math.max(.1,x.confidence-light*.004);const label=learned[x.id]||x.label;return {...x,confidence,label,review:confidence<threshold||label==='Desconhecido'};});}
