export function energyModel({hours=8,idle=4,tariff=.22,standby=true,production=100}){const activeHours=hours*production/100;const activePower=2.8,idlePower=.8,sleepPower=.08;const baseline=activeHours*activePower+idle*idlePower;const optimized=activeHours*activePower+idle*(standby?sleepPower:idlePower);return {baseline,optimized,saved:baseline-optimized,percent:baseline?(baseline-optimized)/baseline*100:0,monthly:(baseline-optimized)*tariff*22,activeHours};}
